  const load=()=>{setError("");setLoadingNotif(true);return api.get("/superadmin/notifications",{params:{type,search}}).then(r=>setItems(Array.isArray(r.data)?r.data:[])).catch(err=>{setItems([]);setError(err?.response?.data?.message||"Unable to load notifications.")}).finally(()=>setLoadingNotif(false))};useEffect(()=>{const timer=setTimeout(load,200);return()=>clearTimeout(timer)},[type,search]);
