  async function refund(item){const id=item.payload?.applicationId;if(!id)return;setError("");try{await api.post(`/superadmin/applications/${id}/refund`);await load()}catch(err){setError(err?.response?.data?.message||"Unable to record the refund.")}}
  async function resendInvite(item){const id=item.payload?.applicationId;if(!id||resending)return;setResending(id);setError("");try{const {data}=await api.post("/superadmin/applications/"+id+"/resend-invite",{});if(!data.emailSent)setError("Invitation link regenerated, but the email was not sent. Check SMTP configuration.");await load()}catch(err){setError(err?.response?.data?.message||"Unable to resend the invitation.")}finally{setResending(null)}}
  const notifEmptyText=items.length?"No notifications match the current filters. Clear the lane or date filter.":"No notifications yet. New registrations, applications, and account actions will appear here.";  const NOTIF_LANES={PENDING:x=>x.type==="PLAN_APPLICATION"&&["NEW","PENDING"].includes(String(x.status||"").toUpperCase()),MONEY:x=>x.type==="PLAN_APPLICATION",FLAGGED:x=>["ACCOUNT_DELETED","ADMIN_DEACTIVATED","ADMIN_DISAPPROVED"].includes(x.type),REFUNDS:x=>x.type==="PLAN_APPLICATION"&&String(x.status||"").toUpperCase()==="REFUNDED"};
  const pendingCount=items.filter(NOTIF_LANES.PENDING).length;const moneyCount=items.filter(NOTIF_LANES.MONEY).length;const flaggedCount=items.filter(NOTIF_LANES.FLAGGED).length;const refundedCount=items.filter(NOTIF_LANES.REFUNDS).length;
  const visibleItems=items.filter(item=>{if(lane!=="ALL"&&!NOTIF_LANES[lane](item))return false;if(range!=="ALL"){const ts=new Date(item.created_at).getTime();if(!Number.isFinite(ts))return false;const now=new Date();const startOfToday=new Date(now.getFullYear(),now.getMonth(),now.getDate()).getTime();if(range==="TODAY"&&ts<startOfToday)return false;if(range!=="TODAY"){const days=range==="7D"?7:30;if(ts<startOfToday-(days-1)*864e5)return false;}}return true;});
