function Health(){
  const c=useColors();const[data,setData]=useState(null);const[error,setError]=useState("");const[loading,setLoading]=useState(true);const[checkedAt,setCheckedAt]=useState(null);
  const load=(silent)=>{if(!silent)setLoading(true);setError("");api.get("/superadmin/health").then(r=>{setData(r.data);setCheckedAt(Date.now())}).catch(err=>{setError(err?.response?.data?.message||"Unable to load system health.");setCheckedAt(Date.now())}).finally(()=>setLoading(false))};
  useEffect(()=>{load(false);const t=setInterval(()=>load(true),30000);return()=>clearInterval(t)},[]);
  if(loading)return <div className="container"><Heading title="System Health"/><LoadingCard text="Checking system health…"/></div>;
  const reqs=Number(data?.live?.requestCount||0);const errs=Number(data?.live?.errorCount||0);
  const errRate=reqs>0?errs/reqs:0;const latencyMs=Number(data?.live?.latencyMs||0);
  const dbOk=!!data?.database?.connected;
  let verdictKey="unknown";let verdictLabel="Checking…";
  if(data){if(!dbOk){verdictKey="down";verdictLabel="Down";}else if(errRate>0.05||latencyMs>1000){verdictKey="degraded";verdictLabel="Degraded";}else{verdictKey="operational";verdictLabel="Operational";}}
  let verdictColor=c.textMuted;
  if(verdictKey==="operational")verdictColor=c.greenFg;else if(verdictKey==="degraded")verdictColor="#d97706";else if(verdictKey==="down")verdictColor=c.redFg;
  const checkedLabel=checkedAt?new Date(checkedAt).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit",second:"2-digit"}):"—";
  const history=data?.history||[];
  return <div className="container"><div className="tw-section-title-action"><Heading title="System Health"/><SuperPressButton tone="blue" onClick={()=>load(false)}>Refresh</SuperPressButton></div>{error&&<ApiMessage text={error}/>}<div className="tw-health-status-row"><section style={card(c)}><ChartTitle title="Application Status" icon="server"/><b style={{color:verdictColor}}>● {verdictLabel}</b><div style={{fontSize:12,marginTop:6,color:c.textMuted}}>Last checked {checkedLabel} · auto-refreshes every 30s</div></section><section style={card(c)}><ChartTitle title="Database Status" icon="classes"/><b style={{color:data?.database?.connected?c.greenFg:c.redFg}}>● {data?.database?.connected?"Connected":"Unavailable"}</b></section></div><div className="tw-health-metrics"><Metric label="Server Uptime" value={`${Math.floor(Number(data?.server?.uptimeSec||0)/3600)}h ${Math.floor((Number(data?.server?.uptimeSec||0)%3600)/60)}m`} icon="server"/><Metric label="CPU Usage" value={`${data?.server?.cpuUsage||0}%`} icon="cpu" tone="#14b8a6"/><Metric label="Memory Usage" value={`${data?.server?.memoryUsage||0}%`} icon="memory" tone="#8b5cf6"/></div><div className="tw-health-grid"><section style={card(c)}><ChartTitle title="System Activity" icon="traffic"/><DualLineChart seriesA={history.map(x=>x.requests||0)} seriesB={history.map(x=>x.errors||0)} labels={history.map((x,i)=>i%10===0?new Date(x.at).toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"}):"" )} labelA="Requests" labelB="Errors" height={240}/></section><section style={card(c)}><ChartTitle title="Platform Records" icon="chart"/><Info label="Users" value={data?.database?.users||0}/><Info label="Sessions" value={data?.database?.sessions||0}/><Info label="Classes" value={data?.database?.classes||0}/><Info label="Platform" value={data?.server?.platform||"—"}/><Info label="Node" value={data?.server?.nodeVersion||"—"}/><Info label="Average latency" value={`${data?.live?.latencyMs||0} ms`}/></section></div></div>;
}

function normalizeSessionMonths(rows){const map=new Map((rows||[]).map(row=>[String(row.month||"").slice(0,7),Number(row.total||0)]));const now=new Date();return Array.from({length:6},(_,index)=>{const date=new Date(now.getFullYear(),now.getMonth()-(5-index),1);const key=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}`;return{month:key,total:map.get(key)||0}})}
function notificationDescription(item){const actor=item?.name||item?.email||"A ThinkWAVE user";return({USER_REGISTERED:`${actor} created a ${String(item?.role||"user").toLowerCase()} account.`,PASSWORD_CHANGED:`${actor} successfully changed the account password.`,INSTITUTION_SETUP:`${actor} completed the institution-name setup.`,ADMIN_DEACTIVATED:`A Superadmin deactivated ${actor}.`,ACCOUNT_DELETED:item?.payload?.deletedBy==="ADMIN"?`An Admin removed ${actor} from the institution.`:`A Superadmin removed ${actor} from ThinkWAVE.`,ADMIN_APPROVED:`A Superadmin approved ${actor}.`,ADMIN_DISAPPROVED:`A Superadmin disapproved ${actor}.`,ADMIN_ACCOUNT_CREATED:`${actor} created the approved institution Admin account.`,ADMIN_INVITE_RESENT:`${actor} resent the Admin invitation email.`,PLAN_APPLICATION:`${actor} submitted a ${item?.payload?.planType === 'PRO' ? 'ThinkWAVE Pro' : 'ThinkWAVE Institution'} application.`,FEEDBACK:`${actor} submitted platform feedback.`}[item?.type]||`${notificationLabel(item?.type)} was recorded by ThinkWAVE.`)}

function notificationLabel(type){return({PLAN_APPLICATION:"Plan application",USER_REGISTERED:"New user registration",INSTITUTION_SETUP:"Institution setup",ACCOUNT_DELETED:"Account removed",PASSWORD_CHANGED:"Password changed",ADMIN_DEACTIVATED:"Admin deactivated",ADMIN_APPROVED:"Admin approved",ADMIN_DISAPPROVED:"Admin disapproved",ADMIN_ACCOUNT_CREATED:"Admin account created",ADMIN_INVITE_RESENT:"Admin invite resent",FEEDBACK:"User feedback"}[type]||String(type||"Platform activity").replaceAll("_"," "))}
function normalizeAccountWeeks(rows){const normalized=(rows||[]).map(row=>({weekStart:row.weekStart||row.week_start,total:Number(row.total||0)}));const map=new Map(normalized.map(row=>[String(row.weekStart||"").slice(0,10),row]));const now=new Date();const monday=new Date(now);monday.setHours(0,0,0,0);monday.setDate(now.getDate()-((now.getDay()+6)%7));return Array.from({length:12},(_,index)=>{const date=new Date(monday);date.setDate(monday.getDate()-(11-index)*7);const key=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`;const row=map.get(key)||{};return{weekStart:key,label:manilaDate(date,{month:"short",day:"numeric"}),total:Number(row.total||0)}})}
function notificationIcon(type){return({PLAN_APPLICATION:"mail",USER_REGISTERED:"user",INSTITUTION_SETUP:"classes",ACCOUNT_DELETED:"trash",PASSWORD_CHANGED:"lock",ADMIN_DEACTIVATED:"alert",ADMIN_APPROVED:"check",ADMIN_DISAPPROVED:"alert",ADMIN_ACCOUNT_CREATED:"user",ADMIN_INVITE_RESENT:"mail",FEEDBACK:"message"}[type]||"bell")}
function notifSeverity(type){if(type==="PLAN_APPLICATION")return"money";if(["ACCOUNT_DELETED","ADMIN_DEACTIVATED","ADMIN_DISAPPROVED"].includes(type))return"danger";return"info"}
function notifSeverityColor(sev,c){return sev==="money"?"#d97706":sev==="danger"?(c.redFg||"#dc2626"):(c.accent||"#2b6cff")}
function notifWorkflow(item){const s=String(item.status||"").toUpperCase();if(item.type==="PLAN_APPLICATION")return s||"PENDING";return s||"RECORDED"}
function relTime(v){const t=new Date(v).getTime();if(!Number.isFinite(t))return"—";const s=Math.max(0,(Date.now()-t)/1e3);if(s<60)return"just now";if(s<3600)return`${Math.floor(s/60)}m ago`;if(s<86400)return`${Math.floor(s/3600)}h ago`;const d=Math.floor(s/86400);return d===1?"yesterday":`${d}d ago`}
